package main

import "strings"

type sqlReferenceKind uint8

const (
	referencePunctuation sqlReferenceKind = iota
	referenceName
	referenceQuotedName
	referenceLiteral
)

type sqlReferenceToken struct {
	text  string
	kind  sqlReferenceKind
	depth int
}

// postgresReferencesColumn checks name roles, not binding across query scopes.
// Literals remain opaque tokens so a typed-literal head cannot become a column.
func postgresReferencesColumn(text string, column string) bool {
	tokens := postgresReferenceTokens(text)
	excluded := make([]bool, len(tokens))
	excludeReferenceDeclarations(tokens, excluded)
	excludeWriteHeaders(tokens, excluded)
	excludeRelationAliases(tokens, excluded)
	excludeOutputAliases(tokens, excluded)
	for i := 0; i < len(tokens); {
		if !tokens[i].isName() {
			i++
			continue
		}
		end := referenceNameEnd(tokens, i)
		last := tokens[end-1]
		if last.text == column && !excluded[i] && !excluded[end-1] && !referenceNameHead(tokens, end) {
			return true
		}
		i = end
	}
	return false
}

func (token sqlReferenceToken) isName() bool {
	return token.kind == referenceName || token.kind == referenceQuotedName
}

func (token sqlReferenceToken) keyword(word string) bool {
	return token.kind == referenceName && token.text == word
}

func (token sqlReferenceToken) punctuation(value string) bool {
	return token.kind == referencePunctuation && token.text == value
}

func postgresReferenceTokens(text string) []sqlReferenceToken {
	out := []byte(text)
	var tokens []sqlReferenceToken
	depth := 0
	for i := 0; i < len(out); {
		token, end := postgresReferenceToken(out, i)
		i = end
		if token.text == "" && token.kind != referenceLiteral {
			continue
		}
		if token.punctuation(")") && depth > 0 {
			depth--
		}
		token.depth = depth
		tokens = append(tokens, token)
		if token.punctuation("(") {
			depth++
		}
	}
	return tokens
}

func postgresReferenceToken(out []byte, i int) (sqlReferenceToken, int) {
	if strings.ContainsRune(" \t\r\n\f\v", rune(out[i])) {
		return sqlReferenceToken{}, i + 1
	}
	if out[i] == '-' && i+1 < len(out) && out[i+1] == '-' {
		return sqlReferenceToken{}, postgresLineEnd(out, i+2)
	}
	if out[i] == '/' && i+1 < len(out) && out[i+1] == '*' {
		return sqlReferenceToken{}, maskBlock(out, i)
	}
	if quote := referenceLiteralQuote(out, i); quote != nil {
		return sqlReferenceToken{kind: referenceLiteral}, maskStringFor(out, quote, "postgresql")
	}
	if out[i] == '$' && postgresDollarDelimiterEnd(out, i) != nil {
		return sqlReferenceToken{kind: referenceLiteral}, maskPostgresDollar(out, i)
	}
	if out[i] == '"' {
		end := postgresIdentifierEnd(out, i)
		if end <= i+1 || out[end-1] != '"' {
			return sqlReferenceToken{kind: referenceLiteral}, end
		}
		name := strings.ReplaceAll(string(out[i+1:end-1]), "\"\"", "\"")
		return sqlReferenceToken{text: name, kind: referenceQuotedName}, end
	}
	if isPostgresTagStart(out[i]) {
		end := referenceWordEnd(out, i)
		return sqlReferenceToken{text: foldPostgresName(string(out[i:end])), kind: referenceName}, end
	}
	if isASCIIDigit(out[i]) {
		end := i + 1
		for end < len(out) && (isPostgresIdentPart(out[end]) || out[end] == '.') {
			end++
		}
		return sqlReferenceToken{kind: referenceLiteral}, end
	}
	if out[i] == ':' && i+1 < len(out) && out[i+1] == ':' {
		return sqlReferenceToken{text: "::"}, i + 2
	}
	return sqlReferenceToken{text: string(out[i : i+1])}, i + 1
}

func referenceLiteralQuote(out []byte, i int) int? {
	if out[i] == '\'' {
		return i
	}
	if i+1 < len(out) && out[i+1] == '\'' && strings.ContainsRune("eEbBxXnN", rune(out[i])) {
		return i + 1
	}
	if i+2 < len(out) && (out[i] == 'u' || out[i] == 'U') && out[i+1] == '&' && out[i+2] == '\'' {
		return i + 2
	}
	return nil
}

func referenceWordEnd(out []byte, i int) int {
	for i < len(out) && isPostgresIdentPart(out[i]) {
		i++
	}
	return i
}

func foldPostgresName(name string) string {
	out := []byte(name)
	for i, value := range out {
		if value >= 'A' && value <= 'Z' {
			out[i] = value + ('a' - 'A')
		}
	}
	return string(out)
}

func referenceNameEnd(tokens []sqlReferenceToken, start int) int {
	end := start + 1
	for end+1 < len(tokens) && tokens[end].punctuation(".") && tokens[end+1].isName() {
		end += 2
	}
	return end
}

func referenceNameHead(tokens []sqlReferenceToken, end int) bool {
	return end < len(tokens) && (tokens[end].punctuation("(") || tokens[end].kind == referenceLiteral)
}

func excludeReferenceDeclarations(tokens []sqlReferenceToken, excluded []bool) {
	cteHeaders := referenceCTEHeaders(tokens)
	for i, token := range tokens {
		if !token.keyword("as") && !token.keyword("collate") && !token.punctuation("::") {
			continue
		}
		if i+1 == len(tokens) || !tokens[i+1].isName() {
			continue
		}
		end := referenceNameEnd(tokens, i+1)
		excludeReferenceRange(excluded, i+1, end)
		if !cteHeaders[i] && end < len(tokens) && tokens[end].punctuation("(") {
			close := referenceParenthesisEnd(tokens, end)
			excludeReferenceRange(excluded, end, close)
		}
	}
}

func referenceParenthesisEnd(tokens []sqlReferenceToken, start int) int {
	for i := start + 1; i < len(tokens); i++ {
		if tokens[i].punctuation(")") && tokens[i].depth == tokens[start].depth {
			return i + 1
		}
	}
	return len(tokens)
}

func excludeReferenceRange(excluded []bool, from int, to int) {
	for i := from; i < to; i++ {
		excluded[i] = true
	}
}

func excludeWriteHeaders(tokens []sqlReferenceToken, excluded []bool) {
	for i, token := range tokens {
		if token.keyword("update") {
			if end := referenceUpdateSet(tokens, i); end >= 0 {
				excludeReferenceRange(excluded, i+1, end)
			}
		}
		if token.keyword("delete") && i+1 < len(tokens) && tokens[i+1].keyword("from") {
			end := referenceDeleteHeaderEnd(tokens, i+2, token.depth)
			excludeReferenceRange(excluded, i+2, end)
		}
	}
}

func referenceUpdateSet(tokens []sqlReferenceToken, start int) int {
	depth := tokens[start].depth
	for i := start + 1; i < len(tokens); i++ {
		if tokens[i].depth < depth || tokens[i].punctuation(";") {
			return -1
		}
		if tokens[i].depth == depth && tokens[i].keyword("set") {
			return i
		}
	}
	return -1
}

func referenceDeleteHeaderEnd(tokens []sqlReferenceToken, start int, depth int) int {
	for i := start; i < len(tokens); i++ {
		token := tokens[i]
		if token.depth < depth || token.punctuation(";") {
			return i
		}
		if token.depth == depth && (token.keyword("where") || token.keyword("using") || token.keyword("returning")) {
			return i
		}
	}
	return len(tokens)
}

func excludeOutputAliases(tokens []sqlReferenceToken, excluded []bool) {
	for i, token := range tokens {
		if !token.keyword("returning") && !token.keyword("select") {
			continue
		}
		start := referenceOutputStart(tokens, i)
		for end := start; end <= len(tokens); end++ {
			if referenceOutputEnd(tokens, end, token) {
				excludeOutputAlias(tokens[start:end], excluded[start:end])
				break
			}
			if tokens[end].depth == token.depth && tokens[end].punctuation(",") {
				excludeOutputAlias(tokens[start:end], excluded[start:end])
				start = end + 1
			}
		}
	}
}

// SELECT modifiers precede its target expressions. RETURNING has no prefix.
func referenceOutputStart(tokens []sqlReferenceToken, owner int) int {
	start := owner + 1
	if !tokens[owner].keyword("select") || start == len(tokens) {
		return start
	}
	if tokens[start].keyword("all") {
		return start + 1
	}
	if !tokens[start].keyword("distinct") {
		return start
	}
	start++
	if start+1 < len(tokens) && tokens[start].keyword("on") && tokens[start+1].punctuation("(") {
		return referenceParenthesisEnd(tokens, start+1)
	}
	return start
}

// Only unqualified clause keywords at the SELECT depth end its target list.
// AS labels, qualified components and IS DISTINCT FROM stay in the expression.
func referenceOutputEnd(tokens []sqlReferenceToken, index int, owner sqlReferenceToken) bool {
	if index == len(tokens) || tokens[index].depth < owner.depth || tokens[index].punctuation(";") {
		return true
	}
	token := tokens[index]
	if !owner.keyword("select") || token.depth != owner.depth || token.kind != referenceName {
		return false
	}
	if tokens[index-1].punctuation(".") || tokens[index-1].keyword("as") ||
		(token.keyword("from") && tokens[index-1].keyword("distinct")) {
		return false
	}
	switch token.text {
	case "group", "order":
		return index+1 < len(tokens) && tokens[index+1].keyword("by")
	case "from", "into", "where", "having", "window", "union", "intersect", "except",
		"limit", "offset", "fetch", "for", "returning":
		return true
	}
	return false
}

func excludeOutputAlias(tokens []sqlReferenceToken, excluded []bool) {
	if len(tokens) < 2 {
		return
	}
	last := len(tokens) - 1
	if tokens[last].isName() && referenceEndsOperand(tokens, last-1) {
		excluded[last] = true
	}
}

func referenceEndsOperand(tokens []sqlReferenceToken, index int) bool {
	token := tokens[index]
	if token.kind == referenceLiteral || token.kind == referenceQuotedName {
		return true
	}
	if token.kind == referencePunctuation {
		if token.punctuation(")") {
			return !referenceClosesOperator(tokens, index)
		}
		return token.punctuation("]")
	}
	if index > 0 && tokens[index-1].punctuation(".") {
		return true
	}
	switch token.text {
	case "as", "collate", "and", "or", "not", "is", "distinct", "from", "like", "ilike", "similar",
		"to", "between", "in", "escape", "at", "time", "zone", "when", "then", "else":
		return false
	}
	return true
}

func referenceClosesOperator(tokens []sqlReferenceToken, close int) bool {
	depth := tokens[close].depth
	for i := close - 1; i >= 0; i-- {
		if tokens[i].depth < depth {
			return false
		}
		if tokens[i].depth == depth && tokens[i].punctuation("(") {
			if i == 0 || !tokens[i-1].keyword("operator") || (i > 1 && tokens[i-2].punctuation(".")) {
				return false
			}
			return referenceOperatorName(tokens[i+1 : close])
		}
	}
	return false
}

func referenceOperatorName(tokens []sqlReferenceToken) bool {
	i := 0
	for i+1 < len(tokens) && tokens[i].isName() && tokens[i+1].punctuation(".") {
		i += 2
	}
	if i == len(tokens) {
		return false
	}
	for ; i < len(tokens); i++ {
		token := tokens[i]
		if token.kind != referencePunctuation || len(token.text) != 1 ||
			!strings.ContainsRune("+-*/<>=~!@#%^&|`?", rune(token.text[0])) {
			return false
		}
	}
	return true
}

package main

// SELECT table declarations cannot satisfy the version guard. Expression
// operands in joins, function arguments and nested queries remain visible.
func excludeRelationAliases(tokens []sqlReferenceToken, excluded []bool) {
	for i, token := range tokens {
		if !token.keyword("select") || (i > 0 && tokens[i-1].punctuation(".")) {
			continue
		}
		if start := referenceSelectFrom(tokens, i); start >= 0 {
			excludeRelationList(tokens, start, excluded)
		}
	}
}

func referenceSelectFrom(tokens []sqlReferenceToken, owner int) int {
	for i := referenceOutputStart(tokens, owner); i < len(tokens); i++ {
		if referenceOutputEnd(tokens, i, tokens[owner]) {
			if tokens[i].keyword("from") {
				return i + 1
			}
			return -1
		}
	}
	return -1
}

// Each factor advances past only its relation head and declarations. The
// sibling walk skips balanced arrays so their commas cannot start a factor.
func excludeRelationList(tokens []sqlReferenceToken, start int, excluded []bool) {
	if start >= len(tokens) {
		return
	}
	depth := tokens[start].depth
	for i := referenceRelationFactor(tokens, start, excluded); i < len(tokens); {
		if referenceRelationEnd(tokens, i, depth) {
			return
		}
		if tokens[i].depth != depth {
			i++
			continue
		}
		if tokens[i].punctuation("[") {
			i = referenceBracketEnd(tokens, i)
			continue
		}
		if tokens[i].punctuation(",") || referenceRelationKeyword(tokens, i, "join") {
			i = referenceRelationFactor(tokens, i+1, excluded)
			continue
		}
		i++
	}
}

func referenceRelationFactor(tokens []sqlReferenceToken, start int, excluded []bool) int {
	index := start
	if index < len(tokens) && tokens[index].keyword("lateral") {
		index++
	}
	if index < len(tokens) && tokens[index].keyword("only") {
		index++
	}
	if index == len(tokens) {
		return index
	}
	if tokens[index].punctuation("(") {
		end := referenceParenthesisEnd(tokens, index)
		excludeParenthesizedRelations(tokens, index, end, excluded)
		return referenceRelationAlias(tokens, end, excluded)
	}
	if !tokens[index].isName() {
		return index + 1
	}
	end := referenceNameEnd(tokens, index)
	excludeReferenceRange(excluded, index, end)
	if tokens[index].keyword("rows") && end < len(tokens) && tokens[end].keyword("from") {
		end++
	}
	if end < len(tokens) && tokens[end].punctuation("(") {
		end = referenceParenthesisEnd(tokens, end)
	}
	if end < len(tokens) && tokens[end].punctuation("*") {
		end++
	}
	return referenceRelationAlias(tokens, end, excluded)
}

// Prefix slices retain original indices. Recursion only enters smaller
// parenthesized table lists, never a derived query's expression body.
func excludeParenthesizedRelations(tokens []sqlReferenceToken, open int, end int, excluded []bool) {
	start := open + 1
	if start >= end-1 || !tokens[end-1].punctuation(")") {
		return
	}
	if tokens[start].keyword("select") || tokens[start].keyword("with") || tokens[start].keyword("values") {
		return
	}
	excludeRelationList(tokens[:end-1], start, excluded[:end-1])
}

func referenceRelationAlias(tokens []sqlReferenceToken, start int, excluded []bool) int {
	if start+1 < len(tokens) && tokens[start].keyword("with") && tokens[start+1].keyword("ordinality") {
		start += 2
	}
	if start < len(tokens) && tokens[start].keyword("as") {
		start++
	}
	if start < len(tokens) && tokens[start].isName() && !referenceRelationBoundary(tokens[start]) {
		excluded[start] = true
		start++
	}
	if start < len(tokens) && tokens[start].punctuation("(") {
		end := referenceParenthesisEnd(tokens, start)
		excludeReferenceRange(excluded, start, end)
		return end
	}
	return start
}

func referenceRelationBoundary(token sqlReferenceToken) bool {
	if token.kind != referenceName {
		return false
	}
	switch token.text {
	case "join", "inner", "left", "right", "full", "cross", "natural", "on", "using",
		"where", "group", "having", "window", "order", "limit", "offset", "fetch", "for",
		"union", "intersect", "except", "returning", "into", "tablesample", "with":
		return true
	}
	return false
}

func referenceRelationEnd(tokens []sqlReferenceToken, index int, depth int) bool {
	token := tokens[index]
	if token.depth < depth || token.punctuation(";") {
		return true
	}
	if token.depth != depth || token.kind != referenceName ||
		(index > 0 && tokens[index-1].punctuation(".")) {
		return false
	}
	switch token.text {
	case "group", "order":
		return index+1 < len(tokens) && tokens[index+1].keyword("by")
	case "where", "having", "window", "limit", "offset", "fetch", "for",
		"union", "intersect", "except", "returning", "into":
		return true
	}
	return false
}

func referenceRelationKeyword(tokens []sqlReferenceToken, index int, word string) bool {
	return tokens[index].keyword(word) && (index == 0 || !tokens[index-1].punctuation("."))
}

func referenceBracketEnd(tokens []sqlReferenceToken, start int) int {
	depth := 1
	for i := start + 1; i < len(tokens); i++ {
		if tokens[i].punctuation("[") {
			depth++
		}
		if tokens[i].punctuation("]") {
			depth--
			if depth == 0 {
				return i + 1
			}
		}
	}
	return len(tokens)
}

package main_test

import (
	"encoding/json/v2"
	"os"
	"testing"
)

func TestPostgresRelationReferenceRoles(t *testing.T) {
	data, err := os.ReadFile("testdata/version-relation-roles.json")
	if err != nil {
		t.Fatal(err)
		return
	}
	var cases []continuedStringCase
	if err := json.Unmarshal(data, &cases); err != nil {
		t.Fatal(err)
		return
	}
	if len(cases) != 30 {
		t.Fatalf("relation reference cases = %d; want 30", len(cases))
		return
	}
	for _, tc := range cases {
		t.Run(tc.Name, func(t *testing.T) {
			diagnostic := ""
			if !tc.Allow {
				diagnostic = "writes versioned table items without version"
			}
			checkVersionCatalogCase(t, versionCatalogCase{
				Name: tc.Name, Columns: []string{"version", "time"}, Option: "version",
				SQL: tc.SQL, Error: diagnostic,
			})
		})
	}
}

package main_test

import (
	"context"
	"encoding/json/v2"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"slices"
	"strconv"
	"strings"
	"testing"
	"time"

	sqlcgen "github.com/gosuda/spira/cmd/sqlc-gen-spira"
)

type sqlcVersionCase struct {
	Name     string   `json:"name"`
	SQL      string   `json:"sql"`
	Columns  []string `json:"columns"`
	Option   string   `json:"option"`
	Text     string   `json:"text"`
	Error    string   `json:"error"`
	Upstream bool     `json:"upstream"`
}

func TestSQLcPostgresVersionPipeline(t *testing.T) {
	root, err := filepath.Abs(filepath.Join("..", ".."))
	if err != nil {
		t.Fatal(err)
		return
	}
	cases, err := readSQLcVersionCases()
	if err != nil {
		t.Fatal(err)
		return
	}
	if len(cases) != 67 {
		t.Fatalf("version pipeline cases = %d; want 67", len(cases))
		return
	}
	work := t.TempDir()
	ctx, cancel := context.WithTimeout(t.Context(), 5*time.Minute)
	defer cancel()
	build := exec.CommandContext(ctx, "logos", "build", "-o", filepath.Join(work, "sqlc-gen-spira"), "./cmd/sqlc-gen-spira")
	build.Dir = root
	if err := runSQLcSQLiteCommand(build); err != nil {
		t.Fatal(err)
		return
	}
	var compiled []sqlcLiteralExpectation
	for _, tc := range cases {
		if tc.Error == "" {
			compiled = append(compiled, sqlcLiteralExpectation{Name: tc.Name, Text: tc.Text})
		}
		t.Run(tc.Name, func(t *testing.T) {
			if err := exerciseSQLcVersionCase(ctx, root, filepath.Join(work, tc.Name), tc); err != nil {
				t.Fatal(err)
			}
		})
	}
	if !t.Failed() {
		if err := checkCompiledSQLcQueries(t, ctx, work, compiled); err != nil {
			t.Fatal(err)
		}
	}
}

func readSQLcVersionCases() ([]sqlcVersionCase, error) {
	data := os.ReadFile("testdata/sqlc-version-pipeline.json")?
	var cases []sqlcVersionCase
	json.Unmarshal(data, &cases)?
	return cases, nil
}

func exerciseSQLcVersionCase(ctx context.Context, root string, dir string, tc sqlcVersionCase) error {
	writeSQLcVersionInput(dir, tc)?
	cmd := exec.CommandContext(ctx, "go", "-C", filepath.Join(root, "tools"), "tool", "sqlc", "generate", "-f", filepath.Join(dir, "sqlc.yaml"))
	cmd.Dir = root
	cmd.Env = append(cmd.Environ(), "SQLCEXPERIMENT=")
	err := runSQLcSQLiteCommand(cmd)
	files := filepath.Glob(filepath.Join(dir, "generated", "*.lgo"))?
	if tc.Error != "" {
		checkSQLcLiteralRefusal(ctx, err, tc.Error, files)?
		return checkSQLcVersionCapture(dir, tc)
	}
	if err != nil {
		return err
	}
	checkSQLcVersionCapture(dir, tc)?
	want := []string{filepath.Join(dir, "generated", "models.sql.lgo"), filepath.Join(dir, "generated", "queries.sql.lgo")}
	if !slices.Equal(files, want) {
		return fmt.Errorf("sqlc generated source files %q; want %q", files, want)
	}
	generated := os.ReadFile(filepath.Join(dir, "generated", "queries.sql.lgo"))?
	if strings.Count(string(generated), "const ContinueItemQuery = ") != 1 {
		return errors.New("generated source must declare exactly one ContinueItemQuery")
	}
	return nil
}

func writeSQLcVersionInput(dir string, tc sqlcVersionCase) error {
	os.Mkdir(dir, 0o755)?
	parts := []string{"id bigint PRIMARY KEY", "name text NOT NULL"}
	for _, name := range tc.Columns {
		column := "\"" + strings.ReplaceAll(name, "\"", "\"\"") + "\""
		parts = append(parts, column+" integer NOT NULL DEFAULT 0")
	}
	schema := "CREATE DOMAIN version AS text;\nCREATE COLLATION version FROM \"C\";\nCREATE TABLE items (" + strings.Join(parts, ", ") + ");\n"
	os.WriteFile(filepath.Join(dir, "schema.sql"), []byte(schema), 0o644)?
	os.WriteFile(filepath.Join(dir, "queries.sql"), []byte("-- name: ContinueItem :exec\n"+tc.SQL+"\n"), 0o644)?
	plugin := filepath.Join(dir, "capture-plugin.sh")
	script := "#!/usr/bin/env bash\nset -euo pipefail\ncapture_dir=\"$(dirname -- \"$0\")\"\ntee \"$capture_dir/request.json\" | \"$capture_dir/../sqlc-gen-spira\" \"$@\"\n"
	os.WriteFile(plugin, []byte(script), 0o755)?
	config := sqlcVersionConfig(plugin, tc.Option)
	return os.WriteFile(filepath.Join(dir, "sqlc.yaml"), []byte(config), 0o644)
}

func sqlcVersionConfig(plugin string, option string) string {
	return fmt.Sprintf(`version: "2"
plugins:
  - name: spira
    process:
      cmd: %s
      format: json
sql:
  - engine: postgresql
    schema: schema.sql
    queries: queries.sql
    codegen:
      - plugin: spira
        out: generated
        options:
          package: generated
          tables:
            items: {type: Item, key: id, key_type: ItemID, version: %s}
`, strconv.Quote(plugin), strconv.Quote(option))
}

func checkSQLcVersionCapture(dir string, tc sqlcVersionCase) error {
	data, err := os.ReadFile(filepath.Join(dir, "request.json"))
	if tc.Upstream {
		if errors.Is(err, os.ErrNotExist) {
			return nil
		}
		if err != nil {
			return fmt.Errorf("inspect upstream SQLc capture: %w", err)
		}
		return errors.New("upstream SQLc refusal invoked the plugin")
	}
	if err != nil {
		return err
	}
	var req sqlcgen.Request
	json.Unmarshal(data, &req)?
	if req.Settings.Engine != "postgresql" || len(req.Queries) != 1 {
		return errors.New("SQLc handoff must contain one PostgreSQL query")
	}
	query := req.Queries[0]
	if query.Name != "ContinueItem" || query.Cmd != ":exec" || query.Filename != "queries.sql" || query.Text != tc.Text {
		return fmt.Errorf("SQLc query handoff = %q; want exact frozen text %q", query.Text, tc.Text)
	}
	var options sqlcgen.PluginOptions
	json.Unmarshal(req.PluginOptions, &options)?
	table, ok := options.Tables["items"]
	if !ok || len(options.Tables) != 1 {
		return errors.New("SQLc options must configure only items")
	}
	if table.Version != tc.Option {
		return fmt.Errorf("SQLc version option = %q; want %q", table.Version, tc.Option)
	}
	return checkSQLcVersionCatalog(req.Catalog, tc.Columns)
}

func checkSQLcVersionCatalog(catalog sqlcgen.Catalog, columns []string) error {
	matched := 0
	for _, schema := range catalog.Schemas {
		for _, table := range schema.Tables {
			if schema.Name == "public" && table.Rel.Name == "items" {
				checkSQLcVersionColumns(table.Columns, columns)?
				matched++
			}
		}
	}
	if matched != 1 {
		return fmt.Errorf("SQLc public.items tables = %d; want 1", matched)
	}
	return nil
}

func checkSQLcVersionColumns(columns []sqlcgen.Column, expected []string) error {
	var names []string
	for _, column := range columns {
		names = append(names, column.Name)
	}
	want := append([]string{"id", "name"}, expected...)
	if !slices.Equal(names, want) {
		return fmt.Errorf("SQLc catalog column names = %q; want %q", names, want)
	}
	return nil
}
